/**
 * Guest age notice: a ONE-TIME self-declaration ("I am 18 or older") asked before the first script is generated by someone who is not signed in.
 * A signed-in user already saw the sign-in notice (components/AuthModal.jsx), so they are never asked. It is a self-declaration, never "age verification":
 * the answer is kept ONLY in this browser (localStorage), nothing is sent to the server, and it blocks nothing beyond that single question.
 */
export const AGE_KEY = 'ls_age_ok_v1';

function store(storage) {
  if (storage) return storage;
  try { return typeof localStorage !== 'undefined' ? localStorage : null; } catch { return null; }
}

export function hasConfirmedAge(storage) {
  try { return store(storage)?.getItem(AGE_KEY) === '1'; } catch { return false; }
}

export function rememberAge(storage) {
  try { store(storage)?.setItem(AGE_KEY, '1'); } catch { /* storage blocked: the question is simply asked again next time */ }
}

/** `status` is next-auth's useSession().status. Only a settled guest ('unauthenticated') who has not confirmed yet is asked. */
export function needsAgeGate({ status, storage } = {}) {
  return status === 'unauthenticated' && !hasConfirmedAge(storage);
}
